TRANSLATIONS = {}
for row in (COPY + GRAPHICS).strip().splitlines():
    if not row.strip():
        continue
    parts = row.split('|')
    if len(parts) != 4:
        raise ValueError(f'Invalid translation row: {row}')
    TRANSLATIONS[parts[0]] = dict(zip(('es', 'zh', 'hi'), parts[1:]))
